      e: "Reserved Instances are not offered for SageMaker instances.",
      f: "There is no SageMaker Capacity Reservation pricing model that gives family-agnostic discounts.",
      g: "Provisioned Throughput is a Bedrock commitment for model inference, not a SageMaker instance discount.",
      h: "Managed Spot Training reduces cost opportunistically but is not a one-year commitment.",
