      c: "Internet egress is the most expensive category, but cross-AZ and cross-Region transfer are also billed.",
      d: "This is reversed; same-AZ private IP traffic is free while cross-AZ traffic is charged.",
      e: "Cross-AZ traffic is charged even over private IPs.",
      f: "There is no such free allowance for cross-AZ transfer.",
      g: "The question describes application-to-database traffic across AZs, which is itself billed.",
