      command: "aws ce get-cost-forecast --time-period Start=2026-10-01,End=2026-12-31 --metric UNBLENDED_COST --granularity MONTHLY --prediction-interval-level 80",
      sampleOutput:
        "{\n  \"Total\": {\n    \"Amount\": \"43871.52\",\n    \"Unit\": \"USD\"\n  },\n  \"ForecastResultsByTime\": [\n    {\n      \"TimePeriod\": {\n        \"Start\": \"2026-10-01\",\n        \"End\": \"2026-11-01\"\n      },\n      \"MeanValue\": \"14210.18\",\n      \"PredictionIntervalLowerBound\": \"13102.44\",\n      \"PredictionIntervalUpperBound\": \"15317.92\"\n    },\n    {\n      \"TimePeriod\": {\n        \"Start\": \"2026-11-01\",\n        \"End\": \"2026-12-01\"\n      },\n      \"MeanValue\": \"14655.07\",\n      \"PredictionIntervalLowerBound\": \"13290.61\",\n      \"PredictionIntervalUpperBound\": \"16019.53\"\n    },\n    {\n      \"TimePeriod\": {\n        \"Start\": \"2026-12-01\",\n        \"End\": \"2026-12-31\"\n      },\n      \"MeanValue\": \"15006.27\",\n      \"PredictionIntervalLowerBound\": \"13401.88\",\n      \"PredictionIntervalUpperBound\": \"16610.66\"\n    }\n  ]\n}",
