    explanation: "Promotional credits are redeemed on the Credits page of the Billing console. Each credit has an expiry date and a list of eligible services; it is applied automatically to eligible charges before the bill is finalized. In an organization with consolidated billing, credit sharing is on by default, so a credit redeemed in one account can offset eligible usage across all member accounts, though the management account can turn sharing off per account. Credits cannot be exchanged for cash and generally do not cover Support charges or taxes.",
