    id: "bill82",
    domain: "billing-pricing-and-support",
    text: "A batch-processing team runs fault-tolerant jobs on EC2 Spot Instances in ap-southeast-1 and sets a maximum price of $0.10 per hour. The current Spot price for the instance type is $0.04 per hour. Which statement correctly describes how the team is charged and how interruptions work?",
    options: [
      { id: "a", text: "The team pays its $0.10 maximum price for every hour the instance runs" },
      { id: "b", text: "The team bids against other customers, and the highest bidder wins the capacity" },
      { id: "c", text: "The Spot Instance can never be interrupted as long as the maximum price is above the Spot price" },
      { id: "d", text: "The team pays the current Spot price of $0.04 per hour, and AWS can reclaim the instance with a two-minute interruption notice when it needs the capacity or the Spot price exceeds the maximum price" },
      { id: "e", text: "The Spot price is locked at $0.04 for the lifetime of the instance" },
      { id: "f", text: "AWS charges the On-Demand rate and refunds the difference at the end of the month" },
      { id: "g", text: "Spot Instances are billed per hour with a minimum of 24 hours" },
      { id: "h", text: "The instance is guaranteed for six hours as a defined-duration block" },
    ],
    correctOptionIds: ["d"],
    explanation: "Spot Instances are charged at the current Spot price in effect for the Availability Zone, not the maximum price you set; the maximum simply caps what you are willing to pay. The Spot price adjusts gradually based on long-term supply and demand, and there is no bidding. AWS can interrupt a Spot Instance with a two-minute warning when it needs the capacity back or when the Spot price rises above your maximum, which is why Spot suits fault-tolerant and flexible workloads.",
    optionRationale: {
      a: "You pay the Spot price, not the maximum price; the maximum is only a ceiling.",
      b: "The bidding model was retired; the Spot price is set by AWS based on long-term trends.",
      c: "AWS can reclaim Spot capacity at any time when it is needed for On-Demand customers, regardless of price.",
      d: "Correct. Billing is at the current Spot price, and interruptions come with a two-minute notice.",
      e: "The Spot price can change while the instance is running; per-second billing reflects the current price.",
      f: "There is no On-Demand-then-refund mechanism; Spot is billed directly at the Spot price.",
      g: "Spot Instances are billed per second (Linux) with no 24-hour minimum.",
      h: "Spot blocks (defined duration) are no longer offered to new customers.",
    },
    referenceUrl: "https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-interruptions.html",
    referenceLabel: "Spot Instance interruptions - Amazon EC2",
