    text: "A company reviewing its EC2 bill notices a new line item for public IPv4 addresses. It has 200 instances, each with a public IPv4 address that is used only for occasional administrative access, plus 15 Elastic IP addresses that are attached to running instances. Which statement about how AWS charges for public IPv4 addresses is correct?",
