    text: "A company runs a mix of EC2, Fargate, and Lambda workloads entirely On-Demand. The FinOps lead wants AWS to look at the last 30 days of usage and recommend an hourly Savings Plans commitment amount, showing the estimated monthly savings and coverage, before the company buys anything. Which feature provides this?",
