    correctOptionIds: ["b"],
    explanation: "Cost Explorer shows daily and monthly data by default. In the Cost Management preferences you can opt in to hourly granularity and resource-level data, after which Cost Explorer retains resource-level, hourly data for the last 14 days (with extended retention available for a fee) so you can filter down to individual resource IDs such as EC2 instances. This is a preference of the account, not a Support plan feature.",
