    text: "A media company serves 500 TB of static images per month directly from an Amazon S3 bucket to users worldwide and is surprised by the size of the S3 data transfer out line item. An architect proposes putting an Amazon CloudFront distribution in front of the bucket. From a pricing standpoint, why does this typically reduce the bill?",
