    explanation: "AWS does not charge for data transfer from an S3 origin to CloudFront edge locations. CloudFront then serves the content to viewers at its own data transfer out rates, which are generally lower than S3 internet egress and decrease further at higher volumes. Because CloudFront caches popular objects at the edge, far fewer requests and bytes are fetched from S3, cutting both request and origin transfer costs.",
